#pragma material(ShadingModel = Unlit, Backend = Graph)

#pragma region Parameters
uniform float A = 1.0;
uniform float B = 2.0;
#pragma endregion

export void M_RtRegions(inout material m)
{
    #pragma region Maths
    float Sum = A + B;
    float Scaled = Sum * 0.5;
    #pragma endregion

    m.EmissiveColor = float3(Scaled, Scaled, Scaled);
    m.Opacity = Scaled;
}

#pragma layout(Node, Var = B, X = -1088, Y = 240)
#pragma layout(Node, Var = A, X = -1088, Y = 80)
#pragma layout(Node, Var = Sum, X = -816, Y = 160)
#pragma layout(Node, Var = Scaled, X = -560, Y = 240)
